"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["59860"],{26408(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.modelo_formulario.declaracao_incompleta","status":422,"titulo":"A declara\xe7\xe3o do modelo de formul\xe1rio est\xe1 ausente ou incompleta"},"descricao":{"codigo":"uniplus.configuracao.modelo_formulario.declaracao_incompleta","requisitos":["UNI-REQ-0144"],"oQueAconteceu":["O corpo da cria\xe7\xe3o de um modelo de formul\xe1rio (`POST /api/configuracao/admin/modelos-formulario`) n\xe3o traz a `declaracao` do modelo, ou traz a `declaracao` sem `serveAFaseDeInscricao` ou sem `obrigatorio`. A declara\xe7\xe3o informa se o modelo serve \xe0 fase de inscri\xe7\xe3o, caso em que traz o conjunto b\xe1sico de dados do candidato, e se ele \xe9 obrigat\xf3rio (ADR-0171). N\xe3o h\xe1 valor assumido: quem cadastra precisa responder \xe0s duas perguntas.","A recusa vem na lista `errors` da resposta, com `field` igual a `declaracao`, junto das demais recusas do cadastro. Como a declara\xe7\xe3o decide quais blocos e pressupostos o modelo admite, a confer\xeancia do conte\xfado contra ela n\xe3o \xe9 feita enquanto a declara\xe7\xe3o est\xe1 incompleta. Nada \xe9 gravado. A declara\xe7\xe3o n\xe3o muda depois que o modelo \xe9 criado, e a edi\xe7\xe3o (`PUT`) n\xe3o a recebe."],"comoResolver":["Envie `declaracao` com `serveAFaseDeInscricao` e `obrigatorio`, cada um verdadeiro ou falso, e repita o pedido."],"ondeAparece":["Cria\xe7\xe3o de um modelo de formul\xe1rio"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Modelo formulario"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"fd5ea0ff72951399d2b2c1a4f29aeb3ea415db44"}}')}}]);